        '<b>가격이 정해지는 방식이 다르다.</b> HBM은 덩어리가 커서 거의 100% 연간 계약이다. 분기 중에 시장이 뜨거워져도 값이 즉각 오르지 않는다. 범용 D램과 낸드는 그때그때 값이 매겨지는 스팟성이라 수급이 빡빡해지면 그 분기에 바로 반영된다.',
