        '<b>어닝 콜에서 걸리는 게 셋 있다.</b> 첫째, 수요와 공급 언급이 1분기와 토씨 하나 다르지 않다. 둘째, 빅테크 투자 둔화 이슈에 축소가 아니라 수익화 본격화라고 답했는데 새 데이터 없이 낙관을 말로 재확인한 셈이다. 셋째, 10여 개 고객과 장기공급계약(LTA, 여러 해치 물량과 가격을 미리 정해두는 계약)을 마무리했다.',
        '<b>LTA 조건이 양쪽 다 불편하다.</b> 통상 5년이 기본인데 상승장에서 파는 쪽의 최선은 짧게 가져가는 것이다. 강세론자는 왜 지금 가격을 묶느냐고 읽고, 약세론자는 회사도 지금이 고점인 걸 아는구나로 읽는다. 억지인데 둘 다 말은 된다.',
        '<b>HBM이 그렇게 팔릴 수밖에 없는 이유도 있다.</b> 규격 통일된 물건을 시장에 던지는 게 아니라 스택당 대역폭·전력 효율·고객별 인증이 가격을 정하고, 특정 GPU에 맞춰 검증을 통과해야 납품돼 사실상 고객 전용으로 라인을 미리 배정한다.',
        '<b>필자는 연말 HBM 판가 협상에 기대를 건다.</b> D램 대폭등은 2026년 초부터인데 하필 그 직전인 작년 연말 시세로 HBM을 협상했다. 올해 말에는 HBM 만드느라 포기한 범용 D램이 이만큼 비싸졌다는 기회비용 논리를 꺼낼 수 있다. 시장이 싫어하는 건 그 사이 6~9개월의 간극일 뿐이라고 본다.',
