        '<b>유가 약발이 다한다.</b> 8월 중순까지 평균 유가는 7월과 거의 같고, 7월 저점 70달러 초반보다 훨씬 높은 80달러 초반에서 널뛴다. 에너지의 마이너스 기여가 사라지거나 플러스로 바뀔 수 있다.',
