        '<b>그런데 설계를 못 바꾼다.</b> 칩 하나 만드는 데 몇 년이 걸리는데 AI 알고리즘은 1~2년마다 갈아엎힌다. 추론 모델·에이전트·확산 방식이 등장하며 "행렬 곱셈만 빠르면 된다"는 전제가 흔들리기 시작했다.',
        '<b>GPU는 명령만 갈아 끼운다.</b> 안에 작은 계산기가 수천 개 들어 있고 무슨 계산을 어떤 순서로 시킬지는 소프트웨어로 정한다. 새 방식이 나와도 칩을 다시 만들 필요가 없다.',
